import React, { useRef, useEffect } from 'react';

export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2, r = size * 0.37;

    // Build morphing blob outline path
    const buildPath = (radiusMod = 0, phaseShift = 0) => {
      const n = 180;
      ctx.beginPath();
      for (let i = 0; i <= n; i++) {
        const a = (i / n) * Math.PI * 2;
        const warp = 1
          + Math.sin(a * 2.0 + t.current * 0.7  + phaseShift) * 0.06 * distort
          + Math.cos(a * 3.1 + t.current * 0.45 + phaseShift) * 0.04 * distort
          + Math.sin(a * 5.2 + t.current * 1.1  + phaseShift) * 0.025 * distort
          + Math.cos(a * 1.3 + t.current * 0.3  + phaseShift) * 0.02 * distort;
        const rr = (r + radiusMod) * warp;
        const x  = cx + Math.cos(a) * rr;
        const y  = cy + Math.sin(a) * rr;
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.closePath();
    };

    const draw = () => {
      t.current += 0.005 * speed;
      ctx.clearRect(0, 0, size, size);

      // ── 1. Outer iridescent glow ring ──────────────────────
      // Multiple layers to fake the rainbow rim light
      const glowColors = [
        { r: r * 0.48, hue: 200 + Math.sin(t.current * 0.3) * 30,   sat: 60, lig: 80, a: 0.14 },
        { r: r * 0.38, hue: 280 + Math.cos(t.current * 0.25) * 25,  sat: 50, lig: 82, a: 0.12 },
        { r: r * 0.28, hue: 340 + Math.sin(t.current * 0.2) * 20,   sat: 55, lig: 85, a: 0.10 },
        { r: r * 0.18, hue: 40  + Math.cos(t.current * 0.35) * 25,  sat: 65, lig: 85, a: 0.08 },
      ];

      glowColors.forEach(({ r: gr, hue, sat, lig, a }) => {
        buildPath(gr);
        const g = ctx.createRadialGradient(cx, cy, r * 0.5, cx, cy, r + gr);
        g.addColorStop(0, `hsla(${hue}, ${sat}%, ${lig}%, 0)`);
        g.addColorStop(0.7, `hsla(${hue}, ${sat}%, ${lig}%, 0)`);
        g.addColorStop(0.85, `hsla(${hue}, ${sat}%, ${lig}%, ${a * 0.5})`);
        g.addColorStop(1, `hsla(${hue}, ${sat}%, ${lig}%, ${a})`);
        ctx.fillStyle = g;
        ctx.fill();
      });

      // ── 2. Clip to main sphere shape ───────────────────────
      buildPath(0);
      ctx.save();
      ctx.clip();

      // Base — nearly white, slightly blue-grey like bubble image 1
      const base = ctx.createRadialGradient(
        cx - r * 0.1,
        cy - r * 0.15,
        0,
        cx + r * 0.15,
        cy + r * 0.2,
        r * 1.1
      );
      base.addColorStop(0,    'rgba(240,238,248,1)');
      base.addColorStop(0.35, 'rgba(220,225,245,1)');
      base.addColorStop(0.65, 'rgba(200,215,240,1)');
      base.addColorStop(1,    'rgba(185,200,232,1)');
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, size, size);

      // Iridescent colour blobs inside — like image 1 and 2
      const colorBlobs = [
        {
          x: cx + Math.sin(t.current * 0.4) * r * 0.28,
          y: cy + r * 0.15 + Math.cos(t.current * 0.3) * r * 0.12,
          r: r * 0.55,
          hue: 175 + Math.sin(t.current * 0.25) * 20,
          sat: 65, lig: 72, a: 0.55,
        },
        {
          x: cx - Math.cos(t.current * 0.35) * r * 0.22,
          y: cy - r * 0.12 + Math.sin(t.current * 0.28) * r * 0.1,
          r: r * 0.6,
          hue: 220 + Math.cos(t.current * 0.2) * 25,
          sat: 55, lig: 68, a: 0.45,
        },
        {
          x: cx + Math.cos(t.current * 0.28) * r * 0.3,
          y: cy - Math.sin(t.current * 0.4) * r * 0.25,
          r: r * 0.45,
          hue: 260 + Math.sin(t.current * 0.18) * 20,
          sat: 50, lig: 72, a: 0.38,
        },
        {
          x: cx + r * 0.1 + Math.sin(t.current * 0.5) * r * 0.15,
          y: cy + r * 0.25 + Math.cos(t.current * 0.38) * r * 0.1,
          r: r * 0.4,
          hue: 40 + Math.cos(t.current * 0.22) * 20,
          sat: 70, lig: 82, a: 0.3,
        },
      ];

      colorBlobs.forEach(blob => {
        const g = ctx.createRadialGradient(blob.x, blob.y, 0, blob.x, blob.y, blob.r);
        g.addColorStop(0, `hsla(${blob.hue}, ${blob.sat}%, ${blob.lig}%, ${blob.a})`);
        g.addColorStop(1, `hsla(${blob.hue}, ${blob.sat}%, ${blob.lig}%, 0)`);
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, size, size);
      });

      // White centre glow — gives the glassy bubble look
      const centre = ctx.createRadialGradient(
        cx - r * 0.08,
        cy - r * 0.12,
        0,
        cx,
        cy,
        r * 0.8
      );
      centre.addColorStop(0,    'rgba(255,255,255,0.82)');
      centre.addColorStop(0.3,  'rgba(255,255,255,0.35)');
      centre.addColorStop(0.65, 'rgba(255,255,255,0.06)');
      centre.addColorStop(1,    'rgba(255,255,255,0)');
      ctx.fillStyle = centre;
      ctx.fillRect(0, 0, size, size);

      // Edge darkening — gives spherical depth
      const edge = ctx.createRadialGradient(cx, cy, r * 0.5, cx, cy, r);
      edge.addColorStop(0, 'transparent');
      edge.addColorStop(0.8, 'rgba(140,160,210,0.08)');
      edge.addColorStop(1,   'rgba(100,130,200,0.22)');
      ctx.fillStyle = edge;
      ctx.fillRect(0, 0, size, size);

      ctx.restore();

      // ── 3. Iridescent rim — drawn ON TOP of sphere edge ───
      buildPath(0);
      ctx.save();
      // Create a rim ring by clipping annulus (outer - inner)
      ctx.clip();
      const rimGrad = ctx.createConicalGradientFallback
        ? null
        : (() => {
          // Use multiple arc strokes to fake conical rainbow rim
          const rimR = r * 1.0;
          const steps = 72;
          for (let i = 0; i < steps; i++) {
            const a1 = (i / steps) * Math.PI * 2 + t.current * 0.15;
            const a2 = ((i + 1.5) / steps) * Math.PI * 2 + t.current * 0.15;
            const hue = (i / steps) * 360;
            ctx.beginPath();
            ctx.arc(cx, cy, rimR, a1, a2);
            ctx.strokeStyle = `hsla(${hue}, 70%, 78%, 0.55)`;
            ctx.lineWidth = r * 0.035;
            ctx.stroke();
          }
        })();
      rimGrad;
      // Execute the rim drawing
      const steps = 72;
      for (let i = 0; i < steps; i++) {
        const a1 = (i / steps) * Math.PI * 2 + t.current * 0.15;
        const a2 = ((i + 1.5) / steps) * Math.PI * 2 + t.current * 0.15;
        const hue = (i / steps) * 360;
        ctx.beginPath();
        ctx.arc(cx, cy, r * 0.97, a1, a2);
        ctx.strokeStyle = `hsla(${hue}, 65%, 78%, 0.45)`;
        ctx.lineWidth = r * 0.045;
        ctx.stroke();
      }
      ctx.restore();

      // ── 4. Soft drop shadow ─────────────────────────────────
      const shadow = ctx.createRadialGradient(cx, cy + r * 0.85, 0, cx, cy + r * 0.9, r * 0.6);
      shadow.addColorStop(0, 'rgba(140,150,200,0.15)');
      shadow.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.ellipse(cx, cy + r * 0.92, r * 0.55, r * 0.1, 0, 0, Math.PI * 2);
      ctx.fillStyle = shadow;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort]);

  return (
    <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />
  );
}
